import{_ as t,o as a,c as o,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"响应式框架","description":"页面的结构和样式，都是写死的。 或者是在不同情况下用相应的结构和样式，但总体而言，是事先写好的； 我们所要做的，是把不停变化的数据放到我们的页面中去，实时更新页面。 一般来说页面的更新有以下因素引起： 纯粹的数据变化，如后端提供的数据变化了，我们页面要相应变化，更新显示新数据。","frontmatter":{"title":"响应式框架","date":"2026-08-11T00:00:00.000Z","categories":["React 系统教程"],"tags":["React","Redux","前端","教程","OneNote","原理与手写实现"],"description":"页面的结构和样式，都是写死的。 或者是在不同情况下用相应的结构和样式，但总体而言，是事先写好的； 我们所要做的，是把不停变化的数据放到我们的页面中去，实时更新页面。 一般来说页面的更新有以下因素引起： 纯粹的数据变化，如后端提供的数据变化了，我们页面要相应变化，更新显示新数据。","sidebarWeight":64,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/实现/响应式框架.md"},"headers":[],"relativePath":"posts/React系统教程/03-原理与手写实现/响应式框架.md","filePath":"posts/React系统教程/03-原理与手写实现/响应式框架.md"}'),l={name:"posts/React系统教程/03-原理与手写实现/响应式框架.md"};function s(r,e,c,_,d,n){return a(),o("div",null,[...e[0]||(e[0]=[i('<div><h1 id="响应式框架" tabindex="-1">响应式框架 <a class="header-anchor" href="#响应式框架" aria-label="Permalink to &quot;响应式框架&quot;">​</a></h1><blockquote><p>本节目标：理解“响应式框架”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><ul><li>页面的结构和样式，都是写死的。</li><li>或者是在不同情况下用相应的结构和样式，但总体而言，是事先写好的；</li><li>我们所要做的，是把不停变化的数据放到我们的页面中去，实时更新页面。</li><li>一般来说页面的更新有以下因素引起： <ul><li>纯粹的数据变化，如后端提供的数据变化了，我们页面要相应变化，更新显示新数据；</li><li>另外是页面发生了交互操作，这些操作要求请求不一样的数据，并将他显示出来；</li></ul></li></ul><p>框架要做的事就是，当以上行为发生时，自动帮我们把新数据更新到页面中去。</p><p>在react 中，我们把数据放在顶级组件中，或者放在组件自己的状态中保存，页面被分成了一个个组件，相当于一个个函数，顶级组件的数据就如同实际上也是全局变量，顶级组件的数据，下面的组件也就是函数都可以访问到，从中取出值来更新自己的页面；</p><p>当然，组件也就是函数也有自己的局部变量，保存着自己的数据；</p></div>',1)])])}const f=t(l,[["render",s]]);export{u as __pageData,f as default};
